// 别忘了装依赖：npm i react-syntax-highlighter`,YP=["语言检测三级：完整文件名（Dockerfile / Makefile / package.json）→ 扩展名 → plain text","主题只保留两套 + 跟随系统。迁移前的 41 套主题桶实测拖出 792KB —— 没人会用到第 20 套主题","偏好按扩展名持久化：给 a.ts 选了 typescript，b.ts 也记住","超过 maxBytes 退化成纯文本并说明原因，而不是让页面卡死","依赖缺失时渲染安装提示面板，不是白屏"],qP=["日志 / 配置文件快速查看","代码附件预览","构建产物 diff 检查（.diff / .patch）"],eS=["react-syntax-highlighter 是 optional peer：不装也能 import 本插件，只是渲染时给出 npm i 提示。","不用 PrismLight + 按需 language：那样每个用户都要手动 registerLanguage，而 prismjs 全语言在 gzip 后约 30KB，不值得为 30KB 增加一个「必须配置才能用」的门槛。","复制按钮在 http 页面（非 secure context）下走 document.execCommand 兜底 —— navigator.clipboard 在那里是 undefined。"],ip={name:HP,description:VP,since:WP,tags:XP,events:GP,methods:KP,methodsNote:JP,config:QP,example:ZP,features:YP,useCases:qP,notes:eS},Xt=Object.assign(BP,{meta:ip}),sp={ImagePreviewPlugin:Wn,VideoPreviewPlugin:Kn,AudioPreviewPlugin:Jn,PdfPreviewPlugin:Xn,OfficePreviewPlugin:Gn,MarkdownPreviewPlugin:qn,CsvPreviewPlugin:rr,ZipPreviewPlugin:or,DocxPreviewPlugin:Zn,MammothDocxPlugin:Yn,PptxPreviewPlugin:El,XlsxPreviewPlugin:nr,JsonPreviewPlugin:Wt,XmlPreviewPlugin:tr,CodePreviewPlugin:Xt,EpubPreviewPlugin:er,DownloadPlugin:Qn};function tS(){return Object.values(sp).map(e=>e())}const nS=Object.freeze(Object.defineProperty({__proto__:null,PLUGIN_FACTORIES:sp,createAllPlugins:tS,createAudioPreviewPlugin:Jn,createCodePreviewPlugin:Xt,createCsvPreviewPlugin:rr,createDocxPreviewPlugin:Zn,createDownloadPlugin:Qn,createEpubPreviewPlugin:er,createImagePreviewPlugin:Wn,createJsonPreviewPlugin:Wt,createMammothDocxPlugin:Yn,createMarkdownPreviewPlugin:qn,createOfficePreviewPlugin:Gn,createPdfPreviewPlugin:Xn,createPptxPreviewPlugin:El,createSimpleReactReaderEpubPlugin:M0,createVideoPreviewPlugin:Kn,createXlsxPreviewPlugin:nr,createXmlPreviewPlugin:tr,createZipPreviewPlugin:or},Symbol.toStringTag,{value:"Module"})),rS=["media","document","data","archive","code","fallback"],ap={media:{label:"图片与音视频",en:"MEDIA",hint:"原生标签承载，零依赖"},document:{label:"文档",en:"DOCUMENT",hint:"PDF / Office / Markdown / EPUB"},data:{label:"结构化数据",en:"DATA",hint:"JSON / XML / 表格"},archive:{label:"压缩包",en:"ARCHIVE",hint:"不下载也能看目录"},code:{label:"代码",en:"CODE",hint:"prism 高亮 + 行号"},fallback:{label:"兜底",en:"FALLBACK",hint:"谁都认不了时仍可下载"}},oS=[{id:"image",dir:"ImagePreviewPlugin",title:"图片预览",en:"IMAGE",group:"media",oneLiner:"一张图放大看细节：缩放、旋转、复位，不重排页面。",why:"用户上传头像、证件照、商品图，需要看清像素级细节时。用 transform 而不是改宽高，所以缩放时周围布局不会跳。",files:["sample.jpg","sample.png","sample.gif","sample.webp","sample.svg"],variants:[{key:"image",label:"默认（maxZoom 5×）"},{key:"image:max",label:"放大到 12×",hint:"maxZoom 调大，按钮与双击复位的上限同步变"}]},{id:"video",dir:"VideoPreviewPlugin",title:"视频预览",en:"VIDEO",group:"media",oneLiner:"浏览器能解的容器直接播；播不了的说清是格式还是编码。",why:"附件里带一段录屏、客服工单带手机拍的视频。它不转码 —— 能不能播完全取决于内核，所以失败文案必须给出可执行的下一步。",files:["sample.mp4","sample.webm","sample.flv","sample.avi"],variants:[{key:"video",label:"默认"},{key:"video:auto",label:"自动播放 + 静音 + 循环",hint:"Chrome/Safari 只在 muted 时允许 autoplay"}],note:"容器 ≠ 编码：这份 sample.flv 里是 H.264，Chromium 实测能播；而 sample.avi 是 DivX，必然播不了。两条路径都能在这页看到。"},{id:"audio",dir:"AudioPreviewPlugin",title:"音频预览",en:"AUDIO",group:"media",oneLiner:"没有封面的纯音频，也有一张能看的卡片。",why:"语音留言、会议录音、客服通话回放。原生 <audio> 的默认控件在各浏览器长得都不一样，所以外面套一层卡片给它一个稳定的落点。",files:["sample.mp3","sample.ogg","sample.wav"],variants:[{key:"audio",label:"默认"},{key:"audio:loop",label:"循环播放",hint:"loop: true"}],stageHeight:300},{id:"pdf",dir:"PdfPreviewPlugin",title:"PDF 预览",en:"PDF",group:"document",oneLiner:"不引 pdfjs —— 把 PDF 交给浏览器自己的查看器。",why:"合同、发票、扫描件。内置查看器自带缩放/翻页/搜索/打印，而且不会为了一个 PDF 往包里塞 300KB 的 pdfjs（以及它的 worker 与字体包）。",files:["star.pdf","danmu.pdf","white-screen.pdf"],variants:[{key:"pdf",label:"默认（iframe）",hint:"本页样本是本站可信静态文件，因此关闭 sandbox"},{key:"pdf:sandbox",label:"默认 sandbox（安全默认）",hint:"不可信文件应保持该策略；部分 Chromium 可能灰底空白"}],stageHeight:520,note:'浏览器对 blob:/data: URL 的 PDF 处理与 http(s) 不一致（部分内核直接下载而不是渲染），所以插件优先用 iframe 指向真实 URL。iframe 默认 sandbox="allow-scripts"（刻意不含 allow-same-origin）；本页样本来自本站 /samples 静态目录、MIME 正确，属可信来源，因此默认档按插件文档的迁移方式显式 sandbox: false 以保证内置查看器可见，另一档保留默认安全策略以便对照。'},{id:"office",dir:"OfficePreviewPlugin",title:"Office 在线预览",en:"OFFICE",group:"document",oneLiner:"公网可达的 office 文档，甩给 Office Online / Google Docs。",why:"后台里预览供应商发来的报价单，文件已经存在自己的 CDN 上。零依赖、零解析，代价是文件 URL 必须公网可达 —— 内网或 blob: 会被在线查看器拒绝。",files:["sample.docx","sample.xlsx","sample.pptx"],variants:[{key:"office",label:"默认（auto）"},{key:"office:google",label:"强制 Google Docs",hint:"viewer: 'google'"}],note:"本页三个样本都是本地路径，所以会稳定落到「这个地址无法用在线查看器打开」说明面板 —— 那正是这条路径的真实形态，不是坏了。"},{id:"docx",dir:"DocxPreviewPlugin",title:"DOCX · 版式还原",en:"DOCX / LAYOUT",group:"document",oneLiner:"要版式就用它：分页、页边距、字号、表格边框照 OOXML 还原。",why:"看合同、公文、简历这类「排版本身有信息量」的文档。它渲染的是带分页的 DOM，和 Word 里看到的样子接近。",files:["sample.docx"],filePatch:{docxMode:"docx-preview"},variants:[{key:"docx",label:"默认（分页）"},{key:"docx:stream",label:"不分页（连续流）",hint:"breakPages: false，适合塞进窄侧栏"}],stageHeight:520},{id:"mammoth-docx",dir:"MammothDocxPlugin",title:"DOCX · 语义 HTML",en:"DOCX / SEMANTIC",group:"document",oneLiner:"要语义就用它：标题/段落/列表/表格转成干净的 HTML。",why:"文档内容要参与站内排版（比如把简历正文塞进详情页），需要的是 <h2>/<ul>/<table> 而不是一堆绝对定位的 div。代价是丢失原版式。",files:["sample.docx"],variants:[{key:"mammoth",label:"默认（带默认样式）"},{key:"mammoth:plain",label:"不带样式",hint:"withDefaultStyle: false，完全交给宿主 CSS"}],stageHeight:520,note:"同一个 sample.docx，这一页和上一页长得完全不一样 —— 这就是「版式还原」与「语义提取」的分工，不是谁对谁错。"},{id:"pptx",dir:"PptxPreviewPlugin",title:"PPTX 大纲",en:"PPTX",group:"document",oneLiner:"没有版式也要能翻：抽出每页文字大纲。",why:"会议材料、培训课件。真要做版式还原得引完整的 OOXML 渲染器（体积不现实），而多数场景只需要「这页讲了什么」。",files:["sample.pptx"],variants:[{key:"pptx",label:"默认"}],stageHeight:480,note:"只抽文字，不渲染图片与形状 —— 所以 sample.pptx 里的大图在这页看不到，这是设计取舍。"},{id:"markdown",dir:"MarkdownPreviewPlugin",title:"Markdown 预览",en:"MARKDOWN",group:"document",oneLiner:"GFM 全套；HTML 默认关 —— 上传的文件不能直接当 HTML 执行。",why:"README、需求文档、知识库条目。用户上传的 .md 里可以塞 <img onerror> 或 <script>，所以 rehype-raw 默认关闭，要开必须显式 allowHtml。",files:["sample.md","xss-demo.md"],variants:[{key:"markdown",label:"默认（HTML 关闭）"},{key:"markdown:raw",label:"allowHtml: true",hint:"不可信 HTML 会进 DOM；on* 事件属性仍被剥掉"}],stageHeight:520,note:"拿 xss-demo.md 切两档：默认档里标签是纯文本，allowHtml 档里图片真的被插进 DOM。onerror 会被剥掉（否则 React 直接抛错把预览打崩），但「不可信 HTML 进了 DOM」这件事本身就是存储型 XSS 的入口。"},{id:"epub",dir:"EpubPreviewPlugin",title:"EPUB 电子书",en:"EPUB",group:"document",oneLiner:"能翻页的电子书，章节隔离在 iframe 里。",why:"阅读类产品里的试读、内部资料。epub.js 把每章渲染进 iframe，所以站内 CSS 与浏览器插件都不会污染正文排版。",files:["sample.epub","fake-book.epub"],variants:[{key:"epub",label:"默认"},{key:"epub:swipe",label:"允许滑动翻页",hint:"swipeable: true"}],stageHeight:560,note:"react-reader + epubjs 合起来 200KB+，是全包最重的可选依赖 —— 所以它只能走子路径引入，不会跟着根入口进来。fake-book.epub 是 zip 改名：插件有两道闸门（magic 是不是 zip + 包里有没有 META-INF/container.xml），认出它不是电子书后不会甩一句 Error loading book，而是把压缩包里**实际有哪些条目**列出来。"},{id:"json",dir:"JsonPreviewPlugin",title:"JSON 树",en:"JSON",group:"data",oneLiner:"大 JSON 不靠折叠猜结构：可搜、可复制路径、可导出。",why:"排查接口响应、看配置文件。纯文本预览要人肉对齐括号，树视图能直接点到某个字段并复制它的路径。",files:["sample.json","package.json"],variants:[{key:"json",label:"默认（跟随系统）"},{key:"json:dark",label:"强制深色",hint:"theme: 'dark'"},{key:"json:expand",label:"默认展开两层",hint:"collapsed: 2"}],stageHeight:480},{id:"xml",dir:"XmlPreviewPlugin",title:"XML / RSS 树",en:"XML",group:"data",oneLiner:"XML / RSS / Atom / KML 共用一套树视图。",why:"对接老系统、订阅源调试、地图数据。带行号与折叠，比在记事本里数尖括号快得多。",files:["sample.xml","sample.rss"],variants:[{key:"xml",label:"默认（展开 2 层）"},{key:"xml:flat",label:"全部展开",hint:"collapsedLevels: 0"}],stageHeight:480},{id:"xlsx",dir:"XlsxPreviewPlugin",title:"XLSX 表格",en:"XLSX",group:"data",oneLiner:"多 Sheet 离线解析，不用装 Excel 也不上传到第三方。",why:"对账、导入前的数据核对。SheetJS 在浏览器里直接解 OOXML，文件不出内网 —— 这一点比「上传到在线预览服务」重要得多。",files:["sample.xlsx"],variants:[{key:"xlsx",label:"默认（首个 Sheet）"},{key:"xlsx:rows",label:"只渲染前 20 行",hint:"maxRows: 20，超大表的截断策略"}],stageHeight:480},{id:"csv",dir:"CsvPreviewPlugin",title:"CSV / TSV 表格",en:"CSV",group:"data",oneLiner:"分隔符和编码自动认，GBK 的表打开不是乱码。",why:"财务导出的表常年是 GBK + 分号；Excel 另存的 TSV 是 Tab。认错了就是「整张表只有一列」或者满屏乱码，用户会以为文件坏了。",files:["sample-data.csv","sample-data-semicolon.csv","sample-data-pipe.csv","sales-data.tsv","gbk-data.csv","mixed-data.csv"],variants:[{key:"csv",label:"默认（每页 50 行）"},{key:"csv:page10",label:"每页 10 行",hint:"pageSize: 10，分页器立刻有得点"}],stageHeight:480,note:"页脚会写「分隔符 |」这类识别结果；工具栏的分隔符下拉在自动模式下显示「自动」。查问题时两处都要看。"},{id:"zip",dir:"ZipPreviewPlugin",title:"ZIP 目录",en:"ZIP",group:"archive",oneLiner:"不下载也能看见压缩包里有什么。",why:"用户上传的交付包、日志打包、素材包。先看目录再决定要不要下 —— 尤其是几 GB 的包。",files:["sample.zip"],variants:[{key:"zip",label:"默认"},{key:"zip:slim",label:"不显示大小",hint:"showFileSize: false"}],stageHeight:480},{id:"code",dir:"CodePreviewPlugin",title:"代码高亮",en:"CODE",group:"code",oneLiner:"100+ 语言、两套主题 —— 41 套主题的桶曾拖出 792KB。",why:"代码评审、工单里贴的脚本、配置文件。语言按扩展名判，主题跟随系统，偏好存 localStorage（可关）。",files:["sample.ts","sample.js","sample.tsx","sample.vue","sample.css","sample.html"],variants:[{key:"code",label:"默认（跟随系统）"},{key:"code:dark",label:"强制深色",hint:"theme: 'dark'"},{key:"code:noline",label:"不要行号",hint:"showLineNumbers: false"}],stageHeight:480,note:"迁移前把 41 套 prism 主题全打进包，单主题桶就有 792KB。现在只留 one-light + vsc-dark-plus，用 auto 跟随 prefers-color-scheme。"},{id:"download",dir:"DownloadPlugin",title:"兜底下载",en:"FALLBACK",group:"fallback",oneLiner:"谁都认不了的时候，至少让文件下得下来。",why:"priority 排最后、认领一切。没有它，未声明支持的格式会落到一片空白 —— 用户连文件名都看不到。",files:["sample.docx","sample.xlsx","sample.pptx"],variants:[{key:"download",label:"默认"},{key:"download:nosize",label:"不显示文件信息",hint:"showFileInfo: false"}],stageHeight:320,note:"这一页只装 DownloadPlugin 一个插件，所以连 .docx 也会落到它手里 —— 这正是兜底的意义。想看正常的 docx 渲染请去「DOCX · 版式」那页。"}],Fu=Object.assign({"../../../src/custom-plugins/AudioPreviewPlugin/doc.json":Df,"../../../src/custom-plugins/CodePreviewPlugin/doc.json":ip,"../../../src/custom-plugins/CsvPreviewPlugin/doc.json":qf,"../../../src/custom-plugins/DocxPreviewPlugin/doc.json":zf,"../../../src/custom-plugins/DownloadPlugin/doc.json":$f,"../../../src/custom-plugins/EpubPreviewPlugin/doc.json":Vf,"../../../src/custom-plugins/ImagePreviewPlugin/doc.json":jf,"../../../src/cust